{
  "items": [
    {
      "question": "What percentage of Earth's water is salt water?",
      "answer": "about 97 percent"
    },
    {
      "question": "What is the name for the loop that moves water between oceans, air, land and living things?",
      "answer": "the water cycle, or the hydrologic cycle"
    },
    {
      "question": "What drives the water cycle?",
      "answer": "The sun drives it"
    },
    {
      "question": "What is the change of liquid water into water vapor?",
      "answer": "Evaporation"
    },
    {
      "question": "What is the process of plants releasing water vapor through their leaves?",
      "answer": "transpiration"
    },
    {
      "question": "What is the term for the total of evaporation from soil and transpiration from plants?",
      "answer": "evapotranspiration"
    },
    {
      "question": "What is the change from gas to liquid called?",
      "answer": "condensation"
    },
    {
      "question": "What is the temperature at which air becomes saturated and condensation begins?",
      "answer": "the dew point"
    },
    {
      "question": "What is the term for water falling from clouds as rain, snow, sleet or hail?",
      "answer": "precipitation"
    },
    {
      "question": "What is the term for water soaking into the ground?",
      "answer": "infiltration"
    },
    {
      "question": "What are layers of rock or sediment that hold enough groundwater to supply a well called?",
      "answer": "aquifers"
    }
  ]
}
